package com.loja.checkout.dominio;

import java.math.BigDecimal;
import java.math.RoundingMode;

final class Dinheiro {

    static final BigDecimal ZERO = BigDecimal.ZERO.setScale(2);

    private Dinheiro() {
    }

    static BigDecimal centavos(BigDecimal valor) {
        return valor.setScale(2, RoundingMode.HALF_EVEN);
    }

    static BigDecimal percentual(BigDecimal base, String taxa) {
        return centavos(base.multiply(new BigDecimal(taxa)));
    }

    static BigDecimal dividir(BigDecimal valor, int partes) {
        return valor.divide(BigDecimal.valueOf(partes), 2, RoundingMode.HALF_EVEN);
    }
}

