    public ResponseEntity<ErroResponse> erroNegocio(ErroNegocio erro) {
        return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(new ErroResponse(erro.codigo().name()));
    }

    public record ErroResponse(String erro) {
    }
}

